-- P04/P05/P07: substitui somente o recálculo de idades, gerações e seu cruzamento com distância.
-- Preserva PDF, totais, coortes e comparativos anteriores; usa coletas novas e notas explícitas.
WITH anterior AS(SELECT result->'rows'->0->'payload' AS payload FROM estudo.notebook_runs WHERE id=81 AND frozen AND status='ok' AND NOT truncated),
fontes AS(SELECT n.id AS run_id,n.cell_id,n.cell_version,r FROM estudo.notebook_runs n CROSS JOIN LATERAL jsonb_array_elements(n.result->'rows') r WHERE ((n.id=90 AND n.cell_id=297 AND n.cell_version=1)) AND n.frozen AND n.status='ok' AND NOT n.truncated AND n.row_count=156),
mapa AS(SELECT *,CASE r->>'bloco'
 WHEN 'idade' THEN 'idades_'||(r->>'sexo')
 WHEN 'origem' THEN 'qualidade_idades_'||(r->>'sexo')
 WHEN 'geracao' THEN 'geracoes_'||(r->>'ano')||'_'||(r->>'sexo')
 WHEN 'geracao_na_distancia' THEN 'geracao_dentro_distancia_'||(r->>'distancia')
 WHEN 'distancia_na_geracao' THEN 'distancia_dentro_geracao_'||(r->>'categoria') END AS serie,
 CASE WHEN r->>'bloco'='distancia_na_geracao' THEN r->>'distancia' ELSE r->>'categoria' END AS categoria
 FROM fontes WHERE r->>'bloco'='geracao' OR (r->>'ano')::integer=2026),
novas AS(SELECT jsonb_build_object('serie',serie,'categoria',categoria,'status','calculado','atual',jsonb_build_object('valor',r->'percentual','contagem',r->'total','denominador',r->'denominador')) AS item FROM mapa
