original_series AS(SELECT x AS s,row_number() OVER() AS ord FROM anterior CROSS JOIN LATERAL jsonb_array_elements(payload->'series')x),
series AS(SELECT coalesce(a.s,p.s) AS s,p.ord FROM original_series p LEFT JOIN alvos a ON a.s->>'id'=p.s->>'id'
 UNION ALL SELECT a.s,1000+row_number() OVER(ORDER BY a.s->>'id') FROM alvos a WHERE NOT EXISTS(SELECT 1 FROM original_series p WHERE p.s->>'id'=a.s->>'id')),
comparacoes AS(SELECT x AS item FROM anterior CROSS JOIN LATERAL jsonb_array_elements(payload->'comparacoes')x WHERE x->>'serie' NOT IN(SELECT jsonb_array_elements_text('["distancia_dentro_geracao_Alfa", "distancia_dentro_geracao_Anteriores a 1946", "distancia_dentro_geracao_Boomers", "distancia_dentro_geracao_Geração X", "distancia_dentro_geracao_Geração Z", "distancia_dentro_geracao_Millennials", "geracao_dentro_distancia_+30 km", "geracao_dentro_distancia_11 a 29 km", "geracao_dentro_distancia_6 a 10 km", "geracao_dentro_distancia_Até 5 km", "geracoes_2026_F", "geracoes_2026_M", "geracoes_2026_geral", "idades_F", "idades_M", "idades_geral", "qualidade_idades_F", "qualidade_idades_M", "qualidade_idades_geral"]'::jsonb)) UNION ALL SELECT item FROM novas)
SELECT payload||jsonb_build_object('meta',payload->'meta'||jsonb_build_object('contrato_versao',3),
 'series',(SELECT jsonb_agg(s ORDER BY ord) FROM series),
 'comparacoes',(SELECT jsonb_agg(item ORDER BY item->>'serie',item->>'categoria') FROM comparacoes),
 'conciliacao','{"pendente": 0, "calculado": 0}'::jsonb||(SELECT jsonb_object_agg(status,n) FROM(SELECT item->>'status' AS status,count(*) AS n FROM comparacoes GROUP BY 1)t)) AS payload
FROM anterior WHERE(SELECT count(*) FROM fontes)=156
AND NOT EXISTS(SELECT 1 FROM fontes WHERE (r->>'total')::bigint>(r->>'denominador')::bigint)
AND (SELECT count(*) FROM novas)>0;
